1	package routerruntime
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"time"
8	
9		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
10		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/postgres"
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/vectorstore"
13	)
14	
15	// VectorStoreRuntime owns the vector-store services shared by the API server
16	// and request-time RAG retrieval.
17	type VectorStoreRuntime struct {
18		FileStore      *vectorstore.FileStore
19		Backend        vectorstore.VectorStoreBackend
20		Manager        *vectorstore.Manager
21		Pipeline       *vectorstore.IngestionPipeline
22		Embedder       vectorstore.Embedder
23		registryCloser io.Closer
24		// drainTimeout bounds how long Shutdown waits for in-flight ingestion jobs
25		// to drain before cancelling them. Sourced from
26		// vector_store.ingestion_drain_timeout_seconds.
27		drainTimeout time.Duration
28	}
29	
30	// defaultDrainTimeout is the fallback shutdown drain bound used when a runtime
31	// is constructed without a configured drain timeout, so Stop is never
32	// unbounded.
33	const defaultDrainTimeout = 30 * time.Second
34	
35	func NewVectorStoreRuntime(cfg *config.RouterConfig) (*VectorStoreRuntime, error) {
36		if cfg == nil {
37			return nil, fmt.Errorf("vector store runtime requires config")
38		}
39		if err := cfg.VectorStore.Validate(); err != nil {
40			return nil, err
41		}
42		cfg.VectorStore.ApplyDefaults()
43	
44		storeReg, fileReg, regCloser, err := buildMetadataRegistries(cfg)
45		if err != nil {
46			return nil, fmt.Errorf("failed to create metadata registry: %w", err)
47		}
48		emitMetadataStoreWarning(cfg)
49	
50		fileStore, err := vectorstore.NewFileStore(cfg.VectorStore.FileStorageDir, fileReg)
51		if err != nil {
52			return nil, fmt.Errorf("failed to create vector store file store: %w", err)
53		}
54	
55		backend, err := vectorstore.NewBackend(cfg.VectorStore.BackendType, buildVectorStoreBackendConfigs(cfg))
56		if err != nil {
57			return nil, fmt.Errorf("failed to create vector store backend: %w", err)
58		}
59	
60		manager := vectorstore.NewManager(backend, storeReg, cfg.VectorStore.EmbeddingDimension, cfg.VectorStore.BackendType)
61	
62		ctx := context.Background()
63		if err := manager.LoadFromRegistry(ctx); err != nil {
64			logging.Warnf("Failed to load vector store registry on startup: %v", err)
65		}
66		if err := fileStore.LoadFromRegistry(ctx); err != nil {
67			logging.Warnf("Failed to load file registry on startup: %v", err)
68		}
69	
70		embedder := vectorstore.NewCandleEmbedder(cfg.VectorStore.EmbeddingModel, cfg.VectorStore.EmbeddingDimension)
71		pipeline := vectorstore.NewIngestionPipeline(backend, fileStore, manager, embedder, vectorstore.PipelineConfig{
72			Workers:   cfg.VectorStore.IngestionWorkers,
73			QueueSize: 100,
74		})
75		pipeline.Start()
76	
77		return &VectorStoreRuntime{
78			FileStore:      fileStore,
79			Backend:        backend,
80			Manager:        manager,
81			Pipeline:       pipeline,
82			Embedder:       embedder,
83			registryCloser: regCloser,
84			drainTimeout:   time.Duration(cfg.VectorStore.IngestionDrainTimeoutSeconds) * time.Second,
85		}, nil
86	}
87	
88	func buildMetadataRegistries(cfg *config.RouterConfig) (vectorstore.StoreRegistry, vectorstore.FileRegistry, io.Closer, error) {
89		switch cfg.VectorStore.MetadataStore {
90		case "postgres":
91			pgCfg := buildVectorStorePostgresConfig(cfg.VectorStore.MetadataPostgres)
92			reg, err := vectorstore.NewPostgresMetadataRegistry(pgCfg)
93			if err != nil {
94				return nil, nil, nil, err
95			}
96			return reg, reg, reg, nil
97		default:
98			reg := vectorstore.NewMemoryMetadataRegistry()
99			return reg, reg, nil, nil
100		}
101	}
102	
103	func buildVectorStorePostgresConfig(src *config.VectorStoreMetadataPostgresConfig) *postgres.Config {
104		return &postgres.Config{
105			Host:            src.Host,
106			Port:            src.Port,
107			Database:        src.Database,
108			User:            src.User,
109			Password:        src.Password,
110			SSLMode:         src.SSLMode,
111			MaxOpenConns:    src.MaxOpenConns,
112			MaxIdleConns:    src.MaxIdleConns,
113			ConnMaxLifetime: src.ConnMaxLifetime,
114			TableName:       src.TableName,
115		}
116	}
117	
118	func emitMetadataStoreWarning(cfg *config.RouterConfig) {
119		if cfg.VectorStore.MetadataStore != "memory" {
120			return
121		}
122		bt := cfg.VectorStore.BackendType
123		if bt == "milvus" || bt == "valkey" || bt == "qdrant" {
124			logging.Warnf(
125				"vector_store.metadata_store is 'memory' but backend_type is '%s'; "+
126					"store metadata will be lost on restart — set metadata_store to 'postgres' for durability",
127				bt,
128			)
129		}
130	}
131	
132	func (r *VectorStoreRuntime) Shutdown() error {
133		if r == nil {
134			return nil
135		}
136		if r.Pipeline != nil {
137			// Fall back to a bounded default if drainTimeout was not configured
138			// (e.g. a hand-constructed runtime), so Stop is never unbounded.
139			drain := r.drainTimeout
140			if drain <= 0 {
141				drain = defaultDrainTimeout
142			}
143			ctx, cancel := context.WithTimeout(context.Background(), drain)
144			defer cancel()
145			if err := r.Pipeline.Stop(ctx); err != nil {
146				logging.Warnf("Ingestion pipeline did not drain within %s: %v", drain, err)
147			}
148		}
149		if r.registryCloser != nil {
150			if err := r.registryCloser.Close(); err != nil {
151				logging.Warnf("Failed to close metadata registry: %v", err)
152			}
153		}
154		if r.Backend != nil {
155			return r.Backend.Close()
156		}
157		return nil
158	}
159	
160	func (r *VectorStoreRuntime) LogInitialized(component string, cfg *config.RouterConfig) {
161		if r == nil || cfg == nil {
162			return
163		}
164		logging.ComponentEvent(component, "vector_store_initialized", map[string]interface{}{
165			"backend": cfg.VectorStore.BackendType,
166			"model":   cfg.VectorStore.EmbeddingModel,
167			"dim":     cfg.VectorStore.EmbeddingDimension,
168			"workers": cfg.VectorStore.IngestionWorkers,
169		})
170	}
171	
172	func buildVectorStoreBackendConfigs(cfg *config.RouterConfig) vectorstore.BackendConfigs {
173		switch cfg.VectorStore.BackendType {
174		case "memory":
175			maxEntries := 100000
176			if cfg.VectorStore.Memory != nil && cfg.VectorStore.Memory.MaxEntriesPerStore > 0 {
177				maxEntries = cfg.VectorStore.Memory.MaxEntriesPerStore
178			}
179			return vectorstore.BackendConfigs{
180				Memory: vectorstore.MemoryBackendConfig{MaxEntriesPerStore: maxEntries},
181			}
182		case "milvus":
183			return vectorstore.BackendConfigs{
184				Milvus: vectorstore.MilvusBackendConfig{
185					Address: fmt.Sprintf("%s:%d", cfg.VectorStore.Milvus.Connection.Host, cfg.VectorStore.Milvus.Connection.Port),
186				},
187			}
188		case "llama_stack":
189			lsCfg := cfg.VectorStore.LlamaStack
190			return vectorstore.BackendConfigs{
191				LlamaStack: vectorstore.LlamaStackBackendConfig{
192					Endpoint:              lsCfg.Endpoint,
193					AuthToken:             lsCfg.AuthToken,
194					EmbeddingModel:        lsCfg.EmbeddingModel,
195					EmbeddingDimension:    cfg.VectorStore.EmbeddingDimension,
196					RequestTimeoutSeconds: lsCfg.RequestTimeoutSeconds,
197					SearchType:            lsCfg.SearchType,
198				},
199			}
200		case "valkey":
201			vCfg := cfg.VectorStore.Valkey
202			return vectorstore.BackendConfigs{
203				Valkey: vectorstore.ValkeyBackendConfig{
204					Host:             vCfg.Host,
205					Port:             vCfg.Port,
206					Password:         vCfg.Password,
207					Database:         vCfg.Database,
208					CollectionPrefix: vCfg.CollectionPrefix,
209					MetricType:       vCfg.MetricType,
210					IndexM:           vCfg.IndexM,
211					IndexEf:          vCfg.IndexEfConstruction,
212					ConnectTimeout:   vCfg.ConnectTimeout,
213				},
214			}
215		case "qdrant":
216			qCfg := cfg.VectorStore.Qdrant
217			return vectorstore.BackendConfigs{
218				Qdrant: vectorstore.QdrantBackendConfig{
219					Host:             qCfg.Host,
220					Port:             qCfg.Port,
221					APIKey:           qCfg.APIKey,
222					UseTLS:           qCfg.UseTLS,
223					CollectionPrefix: qCfg.CollectionPrefix,
224					ConnectTimeout:   qCfg.ConnectTimeout,
225				},
226			}
227		default:
228			return vectorstore.BackendConfigs{}
229		}
230	}
