3	package apiserver
4	
5	import (
6		"context"
7		"math"
8		"net/http"
9		"strings"
10		"time"
11	
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/routerruntime"
13	)
14	
15	type RouterOutcomeRequest struct {
16		ReplayID  string            `json:"replay_id"`
17		Source    string            `json:"source"`
18		Target    string            `json:"target"`
19		TargetRef string            `json:"target_ref,omitempty"`
20		Verdict   string            `json:"verdict"`
21		Reason    string            `json:"reason,omitempty"`
22		Score     *float64          `json:"score,omitempty"`
23		Metadata  map[string]string `json:"metadata,omitempty"`
24	}
25	
26	type RouterOutcomeResponse struct {
27		Success   bool   `json:"success"`
28		Updated   int    `json:"updated"`
29		Recorded  bool   `json:"recorded"`
30		Duplicate bool   `json:"duplicate,omitempty"`
31		Timestamp string `json:"timestamp"`
32	}
33	
34	type routerOutcomeValidationError struct {
35		code    string
36		message string
37	}
38	
39	func (s *ClassificationAPIServer) handleRouterOutcome(w http.ResponseWriter, r *http.Request) {
40		var req RouterOutcomeRequest
41		if err := s.parseJSONRequest(r, &req); err != nil {
42			s.writeJSONRequestError(w, err)
43			return
44		}
45	
46		principal, _ := managementPrincipalFromContext(r.Context())
47		idempotencyKey, source, policyErr := s.learningOutcomeIngestPolicy().enforce(r, principal)
48		if policyErr != nil {
49			s.writeErrorResponse(w, policyErr.Status, policyErr.Code, policyErr.Message)
50			return
51		}
52	
53		outcome, validationErr := normalizeRouterOutcomeRequest(req)
54		if validationErr != nil {
55			s.writeErrorResponse(w, http.StatusBadRequest, validationErr.code, validationErr.message)
56			return
57		}
58		// Provenance is derived from authenticated credentials, never from the body.
59		outcome.Source = source
60		outcome.IdempotencyKey = idempotencyKey
61	
62		runtime := s.currentLearningRuntime()
63		if runtime == nil {
64			s.writeErrorResponse(w, http.StatusServiceUnavailable, "NO_ROUTER_LEARNING_RUNTIME",
65				"Router Learning outcome ingestion requires an active router learning runtime.")
66			return
67		}
68		ctx := r.Context()
69		if ctx == nil {
70			ctx = context.Background()
71		}
72		result := runtime.UpdateOutcome(ctx, outcome)
73		if status, code, message, ok := routerOutcomeResultError(result); ok {
74			s.writeErrorResponse(w, status, code, message)
75			return
76		}
77		s.writeJSONResponse(w, http.StatusOK, RouterOutcomeResponse{
78			Success:   true,
79			Updated:   result.Updated,
80			Recorded:  result.Recorded,
81			Duplicate: result.Code == routerruntime.RouterOutcomeCodeDuplicate,
82			Timestamp: time.Now().UTC().Format(time.RFC3339),
83		})
84	}
85	
86	func routerOutcomeResultError(result routerruntime.RouterOutcomeResult) (status int, code string, message string, isErr bool) {
87		switch result.Code {
88		case routerruntime.RouterOutcomeCodeOK, routerruntime.RouterOutcomeCodeDuplicate:
89			return 0, "", "", false
90		case routerruntime.RouterOutcomeCodeReplayNotFound:
91			return http.StatusNotFound, "REPLAY_NOT_FOUND", firstNonEmpty(result.Message, "replay_id does not reference an owned routing event"), true
92		case routerruntime.RouterOutcomeCodeOwnershipMismatch:
93			return http.StatusConflict, "OUTCOME_OWNERSHIP_MISMATCH", firstNonEmpty(result.Message, "outcome model binding does not match the owned routing event"), true
94		case routerruntime.RouterOutcomeCodeInvalid:
95			return http.StatusBadRequest, "INVALID_OUTCOME", firstNonEmpty(result.Message, "learning outcome is invalid"), true
96		default:
97			if result.Code == "" {
98				return 0, "", "", false
99			}
100			return http.StatusBadRequest, "INVALID_OUTCOME", firstNonEmpty(result.Message, result.Code), true
101		}
102	}
103	
104	func firstNonEmpty(values ...string) string {
105		for _, value := range values {
106			if strings.TrimSpace(value) != "" {
107				return value
108			}
109		}
110		return ""
111	}
112	
113	func normalizeRouterOutcomeRequest(req RouterOutcomeRequest) (*routerruntime.RouterOutcome, *routerOutcomeValidationError) {
114		replayID := strings.TrimSpace(req.ReplayID)
115		if replayID == "" {
116			return nil, &routerOutcomeValidationError{code: "INVALID_OUTCOME", message: "replay_id is required"}
117		}
118		// Body source is optional and ignored for attribution; if provided it must still be a known enum.
119		if strings.TrimSpace(req.Source) != "" {
120			if _, ok := routerOutcomeSource(req.Source); !ok {
121				return nil, &routerOutcomeValidationError{code: "INVALID_OUTCOME", message: "source must be one of user, agent, eval, operator, provider, router"}
122			}
123		}
124		target, ok := routerOutcomeTarget(req.Target)
125		if !ok {
126			return nil, &routerOutcomeValidationError{code: "INVALID_OUTCOME", message: "target must be one of model, route, policy, stability, provider, router"}
127		}
128		verdict, ok := routerOutcomeVerdict(req.Verdict)
129		if !ok {
130			return nil, &routerOutcomeValidationError{code: "INVALID_OUTCOME", message: "verdict must be one of good_fit, underpowered, overprovisioned, failed"}
131		}
132		score := 0.0
133		if req.Score != nil {
134			score = *req.Score
135			if math.IsNaN(score) || math.IsInf(score, 0) || score < 0 || score > 1 {
136				return nil, &routerOutcomeValidationError{code: "INVALID_OUTCOME", message: "score must be between 0.0 and 1.0"}
137			}
138		}
139		return &routerruntime.RouterOutcome{
140			ReplayID:  replayID,
141			Target:    target,
142			TargetRef: boundedOutcomeTargetRef(req.TargetRef),
143			Verdict:   verdict,
144			Reason:    strings.TrimSpace(req.Reason),
145			Score:     score,
146			Metadata:  boundedOutcomeMetadata(req.Metadata),
147		}, nil
148	}
149	
150	func routerOutcomeSource(value string) (routerruntime.RouterOutcomeSource, bool) {
151		switch routerruntime.RouterOutcomeSource(strings.TrimSpace(value)) {
152		case routerruntime.RouterOutcomeSourceUser,
153			routerruntime.RouterOutcomeSourceAgent,
154			routerruntime.RouterOutcomeSourceEval,
155			routerruntime.RouterOutcomeSourceOperator,
156			routerruntime.RouterOutcomeSourceProvider,
157			routerruntime.RouterOutcomeSourceRouter:
158			return routerruntime.RouterOutcomeSource(strings.TrimSpace(value)), true
159		default:
160			return "", false
161		}
162	}
163	
164	func routerOutcomeTarget(value string) (routerruntime.RouterOutcomeTarget, bool) {
165		switch routerruntime.RouterOutcomeTarget(strings.TrimSpace(value)) {
166		case routerruntime.RouterOutcomeTargetModel,
167			routerruntime.RouterOutcomeTargetRoute,
168			routerruntime.RouterOutcomeTargetPolicy,
169			routerruntime.RouterOutcomeTargetStability,
170			routerruntime.RouterOutcomeTargetProvider,
171			routerruntime.RouterOutcomeTargetRouter:
172			return routerruntime.RouterOutcomeTarget(strings.TrimSpace(value)), true
173		default:
174			return "", false
175		}
176	}
177	
178	func routerOutcomeVerdict(value string) (routerruntime.RouterOutcomeVerdict, bool) {
179		switch routerruntime.RouterOutcomeVerdict(strings.TrimSpace(value)) {
180		case routerruntime.RouterOutcomeVerdictGoodFit,
181			routerruntime.RouterOutcomeVerdictUnderpowered,
182			routerruntime.RouterOutcomeVerdictOverprovisioned,
183			routerruntime.RouterOutcomeVerdictFailed:
184			return routerruntime.RouterOutcomeVerdict(strings.TrimSpace(value)), true
185		default:
186			return "", false
187		}
188	}
189	
190	func boundedOutcomeMetadata(metadata map[string]string) map[string]string {
191		if len(metadata) == 0 {
192			return nil
193		}
194		result := make(map[string]string, min(len(metadata), 32))
195		count := 0
196		for key, value := range metadata {
197			if count >= 32 {
198				break
199			}
200			key = strings.TrimSpace(key)
201			value = strings.TrimSpace(value)
202			if key == "" || len(key) > 128 || len(value) > 1024 {
203				continue
204			}
205			result[key] = value
206			count++
207		}
208		if len(result) == 0 {
209			return nil
210		}
211		return result
212	}
213	
214	func boundedOutcomeTargetRef(value string) string {
215		value = strings.TrimSpace(value)
216		if len(value) > 512 {
217			return value[:512]
218		}
219		return value
220	}
221

