261		decisionName string,
262		decisionTier int,
263		model string,
264		verdict routerLearningOutcomeVerdict,
265		score float64,
266	) {
267		key := modelExperienceKey(decisionName, decisionTier, model)
268		exp := rt.experience[key]
269		if exp == nil {
270			exp = &routerLearningModelExperience{
271				QualitySeed: 0.5,
272				SeedWeight:  2,
273			}
274			rt.experience[key] = exp
275		}
276		switch verdict {
277		case routerLearningOutcomeGoodFit:
278			exp.GoodFitCount += outcomeCount(score)
279		case routerLearningOutcomeUnderpowered:
280			exp.UnderpoweredCount += outcomeCount(score)
281		case routerLearningOutcomeOverprovisioned:
282			exp.OverprovisionedCount += outcomeCount(score)
283		case routerLearningOutcomeFailed:
284			exp.FailedCount += outcomeCount(score)
285		}
286		exp.LastUpdated = time.Now()
287	}
