299	func (rt *routerLearningRuntime) experienceSnapshot(decisionName string, decisionTier int, model string) routerLearningModelExperience {
300		if rt == nil || strings.TrimSpace(model) == "" {
301			return defaultRouterLearningModelExperience()
302		}
303		rt.mu.Lock()
304		defer rt.mu.Unlock()
305		for _, key := range []string{
306			modelExperienceKey(decisionName, decisionTier, model),
307			modelExperienceKey("", decisionTier, model),
308			modelExperienceKey("", 0, model),
309		} {
310			if exp := rt.experience[key]; exp != nil {
311				return *exp
312			}
313		}
314		return defaultRouterLearningModelExperience()
315	}
