324	func modelExperienceKey(decisionName string, decisionTier int, model string) string {
325		decisionName = strings.TrimSpace(decisionName)
326		model = strings.TrimSpace(model)
327		if decisionName == "" {
328			decisionName = "_global"
329		}
330		return decisionName + "|" + strconv.Itoa(decisionTier) + "|" + model
331	}
